public int birthday(int[] s, int d, int m) {
    int count = 0;
    for (int i = 0; i + m <= s.length; i++) {
        int sum = 0;
        for (int j = i; j < i + m; j++) {
            sum += s[j];
        }
        if (sum == d) {
            count++;
        }
    }
    return count;
}

code.python:
def birthday(s: list[int], d: int, m: int) -> int:
    count = 0
    for i in range(len(s) - m + 1):
        if sum(s[i:i + m]) == d:
            count += 1
    return count

