code.java:
public int birthday(int[] s, int d, int m) {
    int windowSum = 0;
    int count = 0;
    for (int i = 0; i < s.length; i++) {
        windowSum += s[i];               // element entering on the right
        if (i >= m) {
            windowSum -= s[i - m];       // element that left on the left
        }
        if (i >= m - 1 && windowSum == d) {
            count++;                     // a full window matching d
        }
    }
    return count;
}

code.python:
def birthday(s: list[int], d: int, m: int) -> int:
    window_sum = 0
    count = 0
    for i in range(len(s)):
        window_sum += s[i]               # element entering on the right
        if i >= m:
            window_sum -= s[i - m]       # element that left on the left
        if i >= m - 1 and window_sum == d:
            count += 1                   # a full window matching d
    return count

